:root{--bg:#06101d;--bg2:#0a1727;--panel:#0e1c2d;--panel2:#13243a;--line:#23364e;--text:#eef6ff;--muted:#91a4bb;--accent:#4cc9a6;--gold:#f2c14e;--red:#ff7474;--blue:#6ca8ff;--shadow:0 22px 70px rgba(0,0,0,.22)}
*{box-sizing:border-box}html{scroll-behavior:smooth}body{margin:0;background:radial-gradient(circle at 15% 0,#143451 0,var(--bg) 38%),var(--bg);color:var(--text);font-family:Inter,ui-sans-serif,system-ui,-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif;min-height:100vh}a{color:inherit;text-decoration:none}.nav-shell{height:76px;max-width:1440px;margin:auto;padding:0 28px;display:flex;align-items:center;gap:34px;border-bottom:1px solid rgba(35,54,78,.5)}.brand{display:flex;align-items:center;gap:10px;margin-right:auto}.brand-mark{display:grid;place-items:center;width:36px;height:36px;background:linear-gradient(135deg,var(--accent),#22987e);border-radius:11px;color:#062117;font-weight:950;font-size:1.15rem}.brand b{display:block;letter-spacing:-.025em}.brand small{display:block;color:var(--muted);font-size:.62rem;letter-spacing:.18em}.nav-links{display:flex;gap:6px}.nav-links a{padding:10px 14px;border-radius:10px;color:var(--muted);font-weight:700;font-size:.88rem}.nav-links a:hover,.nav-links a.active{background:rgba(108,168,255,.08);color:var(--text)}.badge{border:1px solid var(--line);padding:9px 13px;border-radius:999px;font-weight:850;font-size:.7rem;letter-spacing:.09em;white-space:nowrap}.badge.live{color:var(--accent);border-color:rgba(76,201,166,.4)}.badge.live i{display:inline-block;width:7px;height:7px;background:var(--accent);border-radius:50%;margin-right:5px;box-shadow:0 0 10px var(--accent)}.badge.warning{color:var(--gold);border-color:rgba(242,193,78,.45)}.alert{max-width:1384px;margin:18px auto 0;padding:13px 17px;background:rgba(242,193,78,.10);border:1px solid rgba(242,193,78,.33);border-radius:13px;color:#ffe8a0;font-size:.9rem}.alert code{background:#07111f;padding:2px 6px;border-radius:6px}main{max-width:1440px;margin:auto;padding:0 28px 60px}.hero{padding:58px 0 34px;display:flex;justify-content:space-between;align-items:end;gap:45px}.hero h1,.page-header h1{font-size:clamp(2.8rem,6vw,5.6rem);line-height:.92;letter-spacing:-.065em;margin:11px 0 20px;max-width:850px}.hero h1 span{color:var(--accent)}.hero p,.page-header p{max-width:730px;color:var(--muted);font-size:1.04rem;line-height:1.7}.hero-status{min-width:260px;border-left:1px solid var(--line);padding-left:22px;margin-bottom:8px}.hero-status span,.hero-status small{display:block;color:var(--muted);font-size:.72rem;text-transform:uppercase;letter-spacing:.1em}.hero-status strong{display:block;margin:8px 0;font-size:1.05rem}.eyebrow{font-size:.7rem;font-weight:850;letter-spacing:.18em;color:var(--accent)}.metrics{display:grid;grid-template-columns:repeat(5,1fr);gap:12px;margin-bottom:18px}.metrics article,.panel{background:linear-gradient(180deg,rgba(19,36,58,.95),rgba(9,23,39,.97));border:1px solid var(--line);box-shadow:var(--shadow)}.metrics article{padding:20px;border-radius:16px}.metrics span{display:block;color:var(--muted);font-size:.7rem;text-transform:uppercase;letter-spacing:.09em;margin-bottom:8px}.metrics strong{display:block;font-size:1.55rem;letter-spacing:-.035em}.metrics small{display:block;color:var(--muted);font-size:.72rem;margin-top:7px}.positive{color:var(--accent)}.negative{color:var(--red)}.panel{padding:25px;border-radius:20px;margin-bottom:18px}.section-head{display:flex;justify-content:space-between;align-items:end;gap:20px;margin-bottom:20px}.section-head h2{margin:4px 0 0;font-size:1.55rem;letter-spacing:-.035em}.muted{color:var(--muted)}.cards{display:grid;grid-template-columns:repeat(3,1fr);gap:14px}.pick-card{background:rgba(5,15,28,.55);border:1px solid var(--line);border-radius:18px;padding:20px;position:relative;overflow:hidden}.pick-card:after{content:"";position:absolute;width:150px;height:150px;border-radius:50%;background:rgba(76,201,166,.07);right:-75px;top:-75px}.pick-top{display:flex;justify-content:space-between;position:relative;z-index:1}.grade{display:inline-grid;place-items:center;min-width:38px;height:38px;padding:0 8px;border-radius:10px;background:var(--accent);color:#062117;font-weight:950}.book{font-size:.7rem;letter-spacing:.1em;font-weight:850;color:var(--blue)}.market-pill{display:inline-block;margin-top:16px;color:var(--muted);font-size:.68rem;text-transform:uppercase;letter-spacing:.12em}.pick-card h3{font-size:1.4rem;margin:8px 0 5px;letter-spacing:-.025em}.matchup{font-size:.83rem;color:var(--muted);margin:0}.price{font-size:2.25rem;font-weight:950;letter-spacing:-.05em;margin:18px 0}dl{display:grid;grid-template-columns:repeat(4,1fr);gap:7px;margin:0}dl div{background:var(--panel2);padding:10px;border-radius:10px}dt{font-size:.61rem;text-transform:uppercase;color:var(--muted);letter-spacing:.07em}dd{margin:4px 0 0;font-weight:850}.stake{margin-top:14px;padding:12px;border:1px solid rgba(76,201,166,.25);background:rgba(76,201,166,.07);border-radius:10px;display:flex;justify-content:space-between}.stake span{color:var(--muted)}details{margin-top:14px;color:var(--muted);font-size:.82rem}summary{cursor:pointer;color:var(--text);font-weight:750}li{margin:6px 0;line-height:1.45}.empty{text-align:center;padding:46px 20px;border:1px dashed var(--line);border-radius:16px}.empty.compact{grid-column:1/-1;padding:25px}.empty h3{margin:8px 0}.empty p{color:var(--muted);max-width:620px;margin:auto;line-height:1.6}.empty-icon{width:42px;height:42px;border:1px solid var(--line);border-radius:50%;display:grid;place-items:center;margin:auto;color:var(--muted)}.slate-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:10px}.game-card{background:rgba(5,15,28,.48);border:1px solid var(--line);border-radius:14px;padding:15px}.game-time{color:var(--muted);font-size:.68rem;text-transform:uppercase;letter-spacing:.08em;margin-bottom:12px}.team-row{display:flex;justify-content:space-between;gap:15px;padding:6px 0}.team-row span{font-size:.87rem}.team-row b{font-size:1rem}.prob-bar{height:5px;background:var(--blue);border-radius:999px;margin-top:10px;overflow:hidden}.prob-bar span{display:block;height:100%;background:var(--accent)}.prob-labels{display:flex;justify-content:space-between;font-size:.68rem;color:var(--muted);margin-top:5px}.game-card small{display:block;color:var(--muted);font-size:.65rem;margin-top:10px}.table-wrap{overflow-x:auto}table{width:100%;border-collapse:collapse;font-size:.84rem}th{text-align:left;color:var(--muted);font-size:.64rem;text-transform:uppercase;letter-spacing:.08em;padding:11px;border-bottom:1px solid var(--line)}td{padding:13px 11px;border-bottom:1px solid rgba(35,54,78,.62);white-space:nowrap}tbody tr:hover{background:rgba(108,168,255,.035)}.result{font-size:.64rem;font-weight:900;padding:5px 8px;border-radius:999px}.result.win{background:rgba(76,201,166,.14);color:var(--accent)}.result.loss{background:rgba(255,116,116,.12);color:var(--red)}.result.push,.result.pending{background:rgba(145,164,187,.12);color:var(--muted)}.text-link{color:var(--accent);font-size:.82rem;font-weight:750}.page-header{padding:56px 0 30px}.page-header h1{font-size:clamp(2.5rem,5vw,4.7rem)}.history-metrics{grid-template-columns:repeat(4,1fr)}footer{max-width:1384px;margin:auto;padding:25px 28px 38px;border-top:1px solid rgba(35,54,78,.45);display:flex;justify-content:space-between;gap:20px;color:var(--muted);font-size:.72rem}
@media(max-width:1150px){.slate-grid{grid-template-columns:repeat(3,1fr)}.cards{grid-template-columns:1fr 1fr}.metrics{grid-template-columns:repeat(3,1fr)}}
@media(max-width:800px){.hero{align-items:flex-start;flex-direction:column}.hero-status{border-left:0;border-top:1px solid var(--line);padding:16px 0 0;width:100%}.metrics{grid-template-columns:1fr 1fr}.cards{grid-template-columns:1fr}.slate-grid{grid-template-columns:1fr 1fr}.nav-shell{padding:0 16px}.nav-links a{padding:9px}.badge{display:none}main{padding:0 14px 45px}.alert{margin:14px 14px 0}.panel{padding:17px}.section-head{align-items:flex-start}.history-metrics{grid-template-columns:1fr 1fr}}
@media(max-width:520px){.nav-shell{height:68px}.brand small{display:none}.hero{padding:40px 0 25px}.hero h1{font-size:2.8rem}.metrics{grid-template-columns:1fr 1fr}.metrics article{padding:15px}.metrics strong{font-size:1.25rem}.slate-grid{grid-template-columns:1fr}dl{grid-template-columns:1fr 1fr}footer{flex-direction:column;padding:22px 16px 30px}.section-head{flex-direction:column}.nav-links{gap:0}}
